const D = { density: .55, energy: .68, speed: 1, scale: 1, persist: .9, hue: 275, x: .5, y: .5, style: 'shell', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const BW = Math.max(360, Math.min(520, Math.round(width / 2.6))), BH = Math.max(80, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1);
  S.dens = new Float32Array(BW * BH); S.chr = new Float32Array(BW * BH);
  S.bw = BW; S.bh = BH; S.px = -5; S.py = 0; S.pz = 0;
}
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1) * 2 - 1; S.pj = fr(2) * 2 - 1; S.px = -5 + fr(3) * 0.6; S.py = fr(4) * 0.5; S.pz = fr(5) * 0.5;
}

const g = S.g, dens = S.dens, chr = S.chr;
const styleI = P.style === 'plasma' ? 1 : P.style === 'ember' ? 2 : P.style === 'ice' ? 3 : P.style === 'pencil' ? 4 : 0;

const sec = K.section;
// Halvorsen 'a' breathes so the triple shell inhales/exhales over minutes
const a = 1.4 + 0.055 * Math.sin(K.t * 0.023) + (sec - 3.5) * 0.010 + S.pj * 0.02;
const dt = 0.005;

// two incommensurate rotation rates (golden-ratio tilt) => perpetual non-repeating motion floor
const r1 = 0.075 + P.speed * 0.11;
const ay = K.t * r1 + A.rms * 0.30 * Math.sin(K.t * 0.6);
const ax = 0.55 + 0.42 * Math.sin(K.t * (r1 * 0.618));
const cay = Math.cos(ay), say = Math.sin(ay), cax = Math.cos(ax), sax = Math.sin(ax);

const fit = 1 / 10, cxo = -2, cyo = -2, czo = -2;
const view = Math.min(BW, BH) * 0.42 * P.scale;
const hbw = BW * 0.5, hbh = BH * 0.5;

const decay = 0.78 + P.persist * 0.20;
for (let i = 0, n = BW * BH; i < n; i++) { dens[i] *= decay; chr[i] *= decay; }

// integrate the Halvorsen ODE many steps/frame, splat bright into fading density buffer
let x = S.px, y = S.py, z = S.pz;
const steps = Math.round((20000 + P.density * 45000) * (BW * BW) / 40000);
for (let s = 0; s < steps; s++) {
  const dx = -a * x - 4 * y - 4 * z - y * y;
  const dy = -a * y - 4 * z - 4 * x - z * z;
  const dz = -a * z - 4 * x - 4 * y - x * x;
  x += dx * dt; y += dy * dt; z += dz * dt;
  if (!(x > -1e4 && x < 1e4) || !(y > -1e4 && y < 1e4) || !(z > -1e4 && z < 1e4)) { x = -5; y = 0; z = 0; continue; }
  const nx = (x - cxo) * fit, ny = (y - cyo) * fit, nz = (z - czo) * fit;
  const rx = nx * cay - nz * say;
  const rz0 = nx * say + nz * cay;
  const ry = ny * cax - rz0 * sax;
  const rz = ny * sax + rz0 * cax;
  const bxi = (hbw + rx * view) | 0, byi = (hbh - ry * view) | 0;
  if (bxi >= 0 && bxi < BW && byi >= 0 && byi < BH) {
    const bi = byi * BW + bxi;
    dens[bi] += 1;
    chr[bi] += (rz * 0.5 + 0.5);
  }
}
S.px = x; S.py = y; S.pz = z;

// violet -> cyan -> gold ramp (the shell identity)
function shellPal(m) {
  m = m < 0 ? 0 : m > 1 ? 1 : m;
  if (m < 0.5) { const t = m * 2; return [0.55 + (0.10 - 0.55) * t, 0.12 + (0.80 - 0.12) * t, 0.90 + (0.95 - 0.90) * t]; }
  const t = (m - 0.5) * 2; return [0.10 + (1.00 - 0.10) * t, 0.80 + (0.80 - 0.80) * t, 0.95 + (0.24 - 0.95) * t];
}
// iq cosine palette for plasma
function iq(m) {
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + 0.00)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + 0.33)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + 0.66))];
}
// hue rotation (deg) applied to chromatic styles so P.hue is live
function rot(r, gg, b, deg) {
  if (deg === 0) return [r, gg, b];
  const mx = Math.max(r, gg, b), mn = Math.min(r, gg, b), d = mx - mn;
  let h = 0;
  if (d > 1e-6) { if (mx === r) h = ((gg - b) / d) % 6; else if (mx === gg) h = (b - r) / d + 2; else h = (r - gg) / d + 4; h *= 60; if (h < 0) h += 360; }
  const sv = mx <= 0 ? 0 : d / mx, v = mx;
  h = (h + deg) % 360; if (h < 0) h += 360;
  const c = v * sv, hp = h / 60, xx = c * (1 - Math.abs(hp % 2 - 1));
  let rr = 0, g2 = 0, b2 = 0;
  if (hp < 1) { rr = c; g2 = xx; } else if (hp < 2) { rr = xx; g2 = c; } else if (hp < 3) { g2 = c; b2 = xx; } else if (hp < 4) { g2 = xx; b2 = c; } else if (hp < 5) { rr = xx; b2 = c; } else { rr = c; b2 = xx; }
  const mm = v - c; return [rr + mm, g2 + mm, b2 + mm];
}

const hueShift = P.hue - 275;
const expo = 0.55 + P.energy * 2.0 + K.intensity * 0.4 + A.bass * 1.2;

g.loadPixels();
const px = g.pixels;
for (let j = 0; j < BH; j++) {
  const cyn = j / BH - 0.5;
  for (let i = 0; i < BW; i++) {
    const bi = j * BW + i;
    const d = dens[bi];
    const dn = 1 - Math.exp(-d * expo * 0.045);
    const avgc = d > 0.0001 ? chr[bi] / d : 0.5;
    const cxn = i / BW - 0.5;
    const vig = Math.exp(-(cxn * cxn + cyn * cyn) * 2.4);
    let r, gg, b;
    if (styleI === 4) { // pencil: graphite hatch on warm paper (abstracted / non-representational)
      const hatch = 0.82 + 0.22 * Math.sin((i + j) * 0.9 + avgc * 6.0);
      const grf = Math.pow(dn, 0.8) * hatch;
      const tone = 1 - Math.min(1, grf) * 0.92;
      r = 0.93 * tone; gg = 0.915 * tone; b = 0.86 * tone;
    } else if (styleI === 2) { // ember: black -> deep red -> orange -> pale gold
      const m = dn;
      r = Math.min(1, m * 2.1);
      gg = Math.min(1, Math.max(0, m * 1.9 - 0.55));
      b = Math.min(1, Math.max(0, m * 2.6 - 1.9));
      const grd = 0.05 * vig; r = Math.min(1, r + grd); gg += grd * 0.25;
      [r, gg, b] = rot(r, gg, b, hueShift);
    } else if (styleI === 3) { // ice: midnight -> glacial cyan -> white
      const m = dn;
      r = Math.min(1, Math.max(0, m * 1.5 - 0.35));
      gg = Math.min(1, m * 1.35 + 0.05);
      b = Math.min(1, m * 1.15 + 0.22);
      const grd = 0.04 + 0.05 * vig; r += grd * 0.3; gg += grd * 0.5; b += grd;
      [r, gg, b] = rot(r, gg, b, hueShift);
    } else if (styleI === 1) { // plasma: iq cosine ribbon by depth+density
      const c = iq(avgc * 0.85 + dn * 0.25 + K.t * 0.02);
      const sh = 0.25 + 0.8 * dn;
      const grd = 0.16 + 0.22 * vig;
      r = Math.min(1, 0.34 * grd + c[0] * sh); gg = Math.min(1, 0.14 * grd + c[1] * sh); b = Math.min(1, 0.5 * grd + c[2] * sh);
      [r, gg, b] = rot(r, gg, b, hueShift);
    } else { // shell (default): violet -> cyan -> gold, density+depth log-mapped, glowing on dark
      const c = shellPal(avgc * 0.62 + dn * 0.42);
      const bright = 0.9 + 0.5 * dn;
      const dnv = 1 - Math.exp(-d * expo * 0.05);
      const gl = 0.17 + 0.30 * vig; // ambient violet ground so frame isn't near-black
      r = Math.min(1, 0.30 * gl + c[0] * dnv * bright);
      gg = Math.min(1, 0.13 * gl + c[1] * dnv * bright);
      b = Math.min(1, 0.55 * gl + c[2] * dnv * bright);
      [r, gg, b] = rot(r, gg, b, hueShift);
    }
    const o = 4 * bi;
    px[o] = r * 255; px[o + 1] = gg * 255; px[o + 2] = b * 255; px[o + 3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio-reactive bloom on the bass -- partial ADD tint, never a full-frame flash (won't strobe)
if ((A.bass > 0.02 || A.treble > 0.02) && styleI !== 4) {
  push(); blendMode(ADD); noStroke();
  const glow = (A.bass * 0.5 + A.treble * 0.35) * (0.4 + P.energy * 0.6);
  fill((P.hue + 25) % 360, 40, 100, glow * 18);
  ellipse(P.x * width, P.y * height, width * 0.85, height * 0.85);
  blendMode(BLEND); pop();
}
